INSERT INTO products (id, name, description, price, category_id, image_url, stock) VALUES
('20000000-0000-0000-0000-000000000123', 'iPhone 13 Pro', 'The iPhone 13 Pro is a cutting-edge smartphone with a powerful camera system, high-performance chip, and stunning display. It offers advanced features for users who demand top-notch technology.', 1099.99, '10000000-0000-0000-0000-000000000001', 'https://cdn.dummyjson.com/product-images/smartphones/iphone-13-pro/thumbnail.webp', 56),
('20000000-0000-0000-0000-000000000078', 'Apple MacBook Pro 14 Inch Space Grey', 'The MacBook Pro 14 Inch in Space Grey is a powerful and sleek laptop, featuring Apple''s M1 Pro chip for exceptional performance and a stunning Retina display.', 1999.99, '10000000-0000-0000-0000-000000000001', 'https://cdn.dummyjson.com/product-images/laptops/apple-macbook-pro-14-inch-space-grey/thumbnail.webp', 24),
('20000000-0000-0000-0000-000000000160', 'Samsung Galaxy Tab S8 Plus Grey', 'The Samsung Galaxy Tab S8 Plus in Grey is a high-performance Android tablet by Samsung. With a large AMOLED display, powerful processor, and S Pen support, it''s ideal for productivity and entertainment.', 599.99, '10000000-0000-0000-0000-000000000001', 'https://cdn.dummyjson.com/product-images/tablets/samsung-galaxy-tab-s8-plus-grey/thumbnail.webp', 62),
('20000000-0000-0000-0000-000000000100', 'Apple Airpods', 'The Apple Airpods offer a seamless wireless audio experience. With easy pairing, high-quality sound, and Siri integration, they are perfect for on-the-go listening.', 129.99, '10000000-0000-0000-0000-000000000001', 'https://cdn.dummyjson.com/product-images/mobile-accessories/apple-airpods/thumbnail.webp', 67),
('20000000-0000-0000-0000-000000000106', 'Apple Watch Series 4 Gold', 'The Apple Watch Series 4 in Gold is a stylish and advanced smartwatch with features like heart rate monitoring, fitness tracking, and a beautiful Retina display.', 349.99, '10000000-0000-0000-0000-000000000001', 'https://cdn.dummyjson.com/product-images/mobile-accessories/apple-watch-series-4-gold/thumbnail.webp', 33),
('20000000-0000-0000-0000-000000000083', 'Blue & Black Check Shirt', 'The Blue & Black Check Shirt is a stylish and comfortable men''s shirt featuring a classic check pattern. Made from high-quality fabric, it''s suitable for both casual and semi-formal occasions.', 29.99, '10000000-0000-0000-0000-000000000002', 'https://cdn.dummyjson.com/product-images/mens-shirts/blue-&-black-check-shirt/thumbnail.webp', 38),
('20000000-0000-0000-0000-000000000177', 'Black Women''s Gown', 'The Black Women''s Gown is an elegant and timeless evening gown. With a sleek black design, it''s perfect for formal events and special occasions, exuding sophistication and style.', 129.99, '10000000-0000-0000-0000-000000000002', 'https://cdn.dummyjson.com/product-images/womens-dresses/black-women''s-gown/thumbnail.webp', 25),
('20000000-0000-0000-0000-000000000182', 'Green Crystal Earring', 'The Green Crystal Earring is a dazzling accessory that features a vibrant green crystal. With a classic design, it adds a touch of elegance to your ensemble, perfect for formal or special occasions.', 29.99, '10000000-0000-0000-0000-000000000002', 'https://cdn.dummyjson.com/product-images/womens-jewellery/green-crystal-earring/thumbnail.webp', 54),
('20000000-0000-0000-0000-000000000007', 'Chanel Coco Noir Eau De', 'Coco Noir by Chanel is an elegant and mysterious fragrance, featuring notes of grapefruit, rose, and sandalwood. Perfect for evening occasions.', 129.99, '10000000-0000-0000-0000-000000000002', 'https://cdn.dummyjson.com/product-images/fragrances/chanel-coco-noir-eau-de/thumbnail.webp', 58),
('20000000-0000-0000-0000-000000000004', 'Red Lipstick', 'The Red Lipstick is a classic and bold choice for adding a pop of color to your lips. With a creamy and pigmented formula, it provides a vibrant and long-lasting finish.', 12.99, '10000000-0000-0000-0000-000000000002', 'https://cdn.dummyjson.com/product-images/beauty/red-lipstick/thumbnail.webp', 91),
('20000000-0000-0000-0000-000000000088', 'Nike Air Jordan 1 Red And Black', 'The Nike Air Jordan 1 in Red and Black is an iconic basketball sneaker known for its stylish design and high-performance features, making it a favorite among sneaker enthusiasts and athletes.', 149.99, '10000000-0000-0000-0000-000000000003', 'https://cdn.dummyjson.com/product-images/mens-shoes/nike-air-jordan-1-red-and-black/thumbnail.webp', 7),
('20000000-0000-0000-0000-000000000090', 'Puma Future Rider Trainers', 'The Puma Future Rider Trainers offer a blend of retro style and modern comfort. Perfect for casual wear, these trainers provide a fashionable and comfortable option for everyday use.', 89.99, '10000000-0000-0000-0000-000000000003', 'https://cdn.dummyjson.com/product-images/mens-shoes/puma-future-rider-trainers/thumbnail.webp', 90),
('20000000-0000-0000-0000-000000000186', 'Calvin Klein Heel Shoes', 'Calvin Klein Heel Shoes are elegant and sophisticated, designed for formal occasions. With a classic design and high-quality materials, they complement your stylish ensemble.', 79.99, '10000000-0000-0000-0000-000000000003', 'https://cdn.dummyjson.com/product-images/womens-shoes/calvin-klein-heel-shoes/thumbnail.webp', 93),
('20000000-0000-0000-0000-000000000187', 'Golden Shoes Woman', 'The Golden Shoes for Women are a glamorous choice for special occasions. Featuring a golden hue and stylish design, they add a touch of luxury to your outfit.', 49.99, '10000000-0000-0000-0000-000000000003', 'https://cdn.dummyjson.com/product-images/womens-shoes/golden-shoes-woman/thumbnail.webp', 88),
('20000000-0000-0000-0000-000000000185', 'Black & Brown Slipper', 'The Black & Brown Slipper is a comfortable and stylish choice for casual wear. Featuring a blend of black and brown colors, it adds a touch of sophistication to your relaxation.', 19.99, '10000000-0000-0000-0000-000000000003', 'https://cdn.dummyjson.com/product-images/womens-shoes/black-&-brown-slipper/thumbnail.webp', 3),
('20000000-0000-0000-0000-000000000172', 'Blue Women''s Handbag', 'The Blue Women''s Handbag is a stylish and spacious accessory for everyday use. With a vibrant blue color and multiple compartments, it combines fashion and functionality.', 49.99, '10000000-0000-0000-0000-000000000004', 'https://cdn.dummyjson.com/product-images/womens-bags/blue-women''s-handbag/thumbnail.webp', 76),
('20000000-0000-0000-0000-000000000173', 'Heshe Women''s Leather Bag', 'The Heshe Women''s Leather Bag is a luxurious and high-quality leather bag for the sophisticated woman. With a timeless design and durable craftsmanship, it''s a versatile accessory.', 129.99, '10000000-0000-0000-0000-000000000004', 'https://cdn.dummyjson.com/product-images/womens-bags/heshe-women''s-leather-bag/thumbnail.webp', 99),
('20000000-0000-0000-0000-000000000174', 'Prada Women Bag', 'The Prada Women Bag is an iconic designer bag that exudes elegance and luxury. Crafted with precision and featuring the Prada logo, it''s a statement piece for fashion enthusiasts.', 599.99, '10000000-0000-0000-0000-000000000004', 'https://cdn.dummyjson.com/product-images/womens-bags/prada-women-bag/thumbnail.webp', 75),
('20000000-0000-0000-0000-000000000175', 'White Faux Leather Backpack', 'The White Faux Leather Backpack is a trendy and practical backpack for the modern woman. With a sleek white design and ample storage space, it''s perfect for both casual and on-the-go styles.', 39.99, '10000000-0000-0000-0000-000000000004', 'https://cdn.dummyjson.com/product-images/womens-bags/white-faux-leather-backpack/thumbnail.webp', 39),
('20000000-0000-0000-0000-000000000176', 'Women Handbag Black', 'The Women Handbag in Black is a classic and versatile accessory that complements various outfits. With a timeless black color and functional design, it''s a must-have in every woman''s wardrobe.', 59.99, '10000000-0000-0000-0000-000000000004', 'https://cdn.dummyjson.com/product-images/womens-bags/women-handbag-black/thumbnail.webp', 11),
('20000000-0000-0000-0000-000000000011', 'Annibale Colombo Bed', 'The Annibale Colombo Bed is a luxurious and elegant bed frame, crafted with high-quality materials for a comfortable and stylish bedroom.', 1899.99, '10000000-0000-0000-0000-000000000005', 'https://cdn.dummyjson.com/product-images/furniture/annibale-colombo-bed/thumbnail.webp', 88),
('20000000-0000-0000-0000-000000000012', 'Annibale Colombo Sofa', 'The Annibale Colombo Sofa is a sophisticated and comfortable seating option, featuring exquisite design and premium upholstery for your living room.', 2499.99, '10000000-0000-0000-0000-000000000005', 'https://cdn.dummyjson.com/product-images/furniture/annibale-colombo-sofa/thumbnail.webp', 60),
('20000000-0000-0000-0000-000000000013', 'Bedside Table African Cherry', 'The Bedside Table in African Cherry is a stylish and functional addition to your bedroom, providing convenient storage space and a touch of elegance.', 299.99, '10000000-0000-0000-0000-000000000005', 'https://cdn.dummyjson.com/product-images/furniture/bedside-table-african-cherry/thumbnail.webp', 64),
('20000000-0000-0000-0000-000000000047', 'Table Lamp', 'The Table Lamp is a functional and decorative lighting solution for your living space. With a modern design, it provides both ambient and task lighting, enhancing the atmosphere.', 49.99, '10000000-0000-0000-0000-000000000005', 'https://cdn.dummyjson.com/product-images/home-decoration/table-lamp/thumbnail.webp', 9),
('20000000-0000-0000-0000-000000000045', 'House Showpiece Plant', 'The House Showpiece Plant is an artificial plant that brings a touch of nature to your home without the need for maintenance. It adds greenery and style to any space.', 39.99, '10000000-0000-0000-0000-000000000005', 'https://cdn.dummyjson.com/product-images/home-decoration/house-showpiece-plant/thumbnail.webp', 28),
('20000000-0000-0000-0000-000000000066', 'Microwave Oven', 'The Microwave Oven is a versatile kitchen appliance for quick and efficient cooking, reheating, and defrosting. Its compact size makes it suitable for various kitchen setups.', 89.99, '10000000-0000-0000-0000-000000000005', 'https://cdn.dummyjson.com/product-images/kitchen-accessories/microwave-oven/thumbnail.webp', 59),
('20000000-0000-0000-0000-000000000061', 'Hand Blender', 'The Hand Blender is a versatile kitchen appliance for blending, pureeing, and mixing. Its compact design and powerful motor make it a convenient tool for various recipes.', 34.99, '10000000-0000-0000-0000-000000000005', 'https://cdn.dummyjson.com/product-images/kitchen-accessories/hand-blender/thumbnail.webp', 84),
('20000000-0000-0000-0000-000000000056', 'Electric Stove', 'The Electric Stove provides a portable and efficient cooking solution. Ideal for small kitchens or as an additional cooking surface for various culinary needs.', 49.99, '10000000-0000-0000-0000-000000000005', 'https://cdn.dummyjson.com/product-images/kitchen-accessories/electric-stove/thumbnail.webp', 21),
('20000000-0000-0000-0000-000000000052', 'Carbon Steel Wok', 'The Carbon Steel Wok is a versatile cooking pan suitable for stir-frying, sautéing, and deep frying. Its sturdy construction ensures even heat distribution for delicious meals.', 29.99, '10000000-0000-0000-0000-000000000005', 'https://cdn.dummyjson.com/product-images/kitchen-accessories/carbon-steel-wok/thumbnail.webp', 40),
('20000000-0000-0000-0000-000000000068', 'Pan', 'The Pan is a versatile and essential cookware item for frying, sautéing, and cooking various dishes. Its non-stick coating ensures easy food release and cleanup.', 24.99, '10000000-0000-0000-0000-000000000005', 'https://cdn.dummyjson.com/product-images/kitchen-accessories/pan/thumbnail.webp', 90);
